documents.empty_artifact:
yamaa: "1.0"
type: spec
domain: OUT
base: SRC
keys: [STUDYID, USUBJID]
input: {SRC: input.csv}
columns:
  - {name: STUDYID, type: str, derivation: SRC.STUDYID}
  - {name: USUBJID, type: str, derivation: SRC.USUBJID}
verifications:
  - row_count: {max_fraction: 0}
output: {path: out.csv, columns: [STUDYID, USUBJID]}

documents.gated_assertion:
yamaa: "1.0"
type: spec
domain: OUT
base: SRC
keys: [STUDYID, USUBJID]
input: {SRC: {path: input.csv, types: {VAL: int}}}
columns:
  - {name: STUDYID, type: str, derivation: SRC.STUDYID}
  - {name: USUBJID, type: str, derivation: SRC.USUBJID}
  - {name: GATE, type: str, derivation: SRC.GATE}
  - {name: VAL, type: int, derivation: SRC.VAL}
verifications:
  - assert: {when: "GATE = 'Y'", require: 'VAL > 0'}
output: {path: out.csv, columns: [STUDYID, USUBJID, GATE, VAL]}
